mapper.select:
/* UploadJobMapper.selectNextJobId */
SELECT CONCAT('U', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'USER_UPLOAD_JOB_ID'))
  FROM DUAL

mapper.insert:
/* UploadJobMapper.insertUploadJob */
INSERT INTO TB_USER_UPLOAD_JOB (
      JOB_ID
    , CMPNY_CD
    , USER_CD
    , FILE_NAME
    , FILE_SIZE
    , TOTAL_ROWS
    , PROCESSED_ROWS
    , SUCCESS_COUNT
    , FAIL_COUNT
    , STATUS
    , INSERT_NO
)
VALUES (
      #{jobId}
    , #{cmpnyCd}
    , #{userCd}
    , #{fileName}
    , #{fileSize}
    , #{totalRows}
    , 0
    , 0
    , 0
    , 'PENDING'
    , #{insertNo}
)

mapper.update:
/* UploadJobMapper.updateUploadJobProgress */
UPDATE TB_USER_UPLOAD_JOB
   SET STATUS         = #{status}
     , PROCESSED_ROWS = PROCESSED_ROWS + #{successInc} + #{failInc}
     , SUCCESS_COUNT  = SUCCESS_COUNT + #{successInc}
     , FAIL_COUNT     = FAIL_COUNT + #{failInc}
     , UPDATE_NO      = #{updateNo}
     , UPDATE_DATE    = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND JOB_ID   = #{jobId}

/* UploadJobMapper.updateUploadJobFinal */
UPDATE TB_USER_UPLOAD_JOB
   SET STATUS      = #{status}
     , FAILS_JSON  = #{failsJson}
     , ERROR_MSG   = #{errorMsg}
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND JOB_ID   = #{jobId}
